import { useCallback, useEffect, useMemo, useRef, useState } from 'react';

import { FilterDataAccessor } from 'domain/Filter';
import {
  usePageFilterApplied,
  usePageFilterData,
  usePageFilterManagement,
  usePageFilterStatus,
} from 'hooks';
import { FilterForm, FilterValue } from 'models/Filters';

import { COMMERCIAL_RESULTS_PAGE_NAME } from '../../constants';

type CommercialDrillKey =
  | 'region'
  | 'brands'
  | 'sub_brands'
  | 'channel'
  | 'pack_type'
  | 'sku';

const DRILLDOWN_HIERARCHY: readonly CommercialDrillKey[] = [
  'region',
  'brands',
  'sub_brands',
  'channel',
  'pack_type',
  'sku',
];

const EMPTY_VALUES = new Set(['', 'ALL', 'All']);

const hasSpecificValue = (value: unknown): boolean => {
  if (value === undefined || value === null) return false;
  if (typeof value !== 'string') return true;
  return !EMPTY_VALUES.has(value);
};

export const useCommercialResultsBreadcrumb = () => {
  const { applied } = usePageFilterApplied(COMMERCIAL_RESULTS_PAGE_NAME);
  const { defaults, dataFilters } = usePageFilterData(
    COMMERCIAL_RESULTS_PAGE_NAME,
  );

  const { isLoading } = usePageFilterStatus(COMMERCIAL_RESULTS_PAGE_NAME);
  const { updateAllForm, apply } = usePageFilterManagement(
    COMMERCIAL_RESULTS_PAGE_NAME,
  );

  const appliedRef = useRef(applied);
  appliedRef.current = applied;

  const defaultsRef = useRef(defaults);
  defaultsRef.current = defaults;

  const rootLabel = String(
    FilterDataAccessor.getInstance().getCountry(dataFilters, applied)?.label ??
      '',
  );

  // Tracks the chronological selection order. Initialised from `nav_cr_order`
  // so the sequence survives a page reload.
  const [navigationOrder, setNavigationOrder] = useState<CommercialDrillKey[]>(
    () => {
      const params = new URLSearchParams(globalThis.location.search);
      const raw = params.get('nav_cr_order');
      if (!raw) return [];
      return raw
        .split(',')
        .filter((k): k is CommercialDrillKey =>
          (DRILLDOWN_HIERARCHY as readonly string[]).includes(k),
        );
    },
  );

  // Effect 1 — diff applied vs. previous applied to keep navigationOrder in sync.
  const prevAppliedRef = useRef<FilterForm | undefined>(undefined);
  useEffect(() => {
    const prev = prevAppliedRef.current;
    prevAppliedRef.current = applied;
    if (!prev) return; // skip first render

    setNavigationOrder((prevOrder) => {
      let order = [...prevOrder];
      for (const key of DRILLDOWN_HIERARCHY) {
        const wasSpecific = hasSpecificValue(prev?.[key]);
        const isSpecific = hasSpecificValue(applied?.[key]);
        if (!wasSpecific && isSpecific && !order.includes(key)) {
          order = [...order, key];
        } else if (wasSpecific && !isSpecific) {
          order = order.filter((k) => k !== key);
        }
      }
      return order;
    });
  }, [applied]);

  // Effect 2 — persists navigationOrder to the URL as `nav_cr_order`.
  // Skipped on the very first render so we don't redundantly rewrite the URL
  // value we just read during state initialisation.
  const isFirstNavigationMount = useRef(true);

  useEffect(() => {
    if (isFirstNavigationMount.current) {
      isFirstNavigationMount.current = false;
      return;
    }
    const params = new URLSearchParams(globalThis.location.search);
    if (navigationOrder.length > 0) {
      params.set('nav_cr_order', navigationOrder.join(','));
    } else {
      params.delete('nav_cr_order');
    }
    globalThis.history.replaceState({}, '', `?${params.toString()}`);
  }, [navigationOrder]);

  // path is ordered chronologically (by selection sequence)
  const { path, pathWithKeys } = useMemo(() => {
    const chips: string[] = [];
    const keyed: { label: string; key: CommercialDrillKey }[] = [];

    for (const key of navigationOrder) {
      const value = applied?.[key as keyof typeof applied];
      if (hasSpecificValue(value)) {
        chips.push(String(value));
        keyed.push({ label: String(value), key });
      }
    }

    return { path: chips, pathWithKeys: keyed };
  }, [applied, navigationOrder]);

  const pathWithKeysRef = useRef(pathWithKeys);
  pathWithKeysRef.current = pathWithKeys;

  /**
   * Navigates back to a specific breadcrumb step.
   *
   * Keeps every chip at index ≤ pathIndex and clears all drilldown keys not
   * represented in that kept set. Because the path is chronologically ordered
   * (not hierarchy-ordered), we cannot simply slice DRILLDOWN_HIERARCHY —
   * instead we derive keysToClean as the complement of keysToKeep.
   *
   * - pathIndex >= 0: keeps chips[0..pathIndex], clears everything else
   * - pathIndex < 0 (e.g. -1): clears all drilldown levels (root chip action)
   */
  const goToStep = useCallback(
    (pathIndex: number) => {
      const chips = pathWithKeysRef.current;

      const keysToKeep = new Set(
        pathIndex >= 0 ? chips.slice(0, pathIndex + 1).map((c) => c.key) : [],
      );
      const keysToClean = DRILLDOWN_HIERARCHY.filter(
        (key) => !keysToKeep.has(key),
      );

      if (keysToClean.length === 0) return;

      const clearedFilters = keysToClean.reduce<Record<string, FilterValue>>(
        (acc, key) => {
          const defaultValue = defaultsRef.current?.[key] ?? null;
          // If defaults[key] is itself a specific value (e.g. SKU defaults to
          // the first available item after tier refresh, not a sentinel like
          // 'ALL'), fall back to null so we actually clear the filter.
          const clearValue = hasSpecificValue(defaultValue)
            ? null
            : defaultValue;

          return { ...acc, [key]: clearValue };
        },
        {},
      );

      updateAllForm({ ...appliedRef.current, ...clearedFilters });
      apply();
    },
    [apply, updateAllForm],
  );

  return { rootLabel, path, goToStep, isLoading };
};
